-- =============================================================================
-- HARPIA DESUP — Cargo e disciplina dos professores (planilha TRAB.pdf)
-- Supabase / PostgreSQL. Idempotente, numa única transação. FAÇA BACKUP antes.
--
-- O QUE FAZ (somente UPDATE em professores que JÁ EXISTEM; casa por ID funcional)
--  1) CARGO  : troca o tipo de contrato (tipo_contrato_id) pelo tipo cujo NOME é
--              idêntico ao NOME_CARGO da planilha. Cargo sem tipo de contrato
--              correspondente no sistema NÃO é alterado (veja o relatório do final).
--  2) DISCIPLINA: grava a DISCIPLINA da planilha em area_atuacao (substitui o valor atual
--              quando a planilha traz um valor).
--
-- O QUE NÃO FAZ
--  - Não cria professores nem tipos de contrato, não apaga nada, não mexe em nome,
--    matrícula, unidades ou carga. Linhas sem cargo/disciplina na planilha são ignoradas.
--  - ATENÇÃO: o tipo de contrato define os limites de horas do professor; trocar o cargo
--    muda o limite dele (horas em sala, total, turmas).
--
-- QUAL LINHA É USADA QUANDO O MESMO ID APARECE MAIS DE UMA VEZ (mais de um vínculo)
--  - a linha cuja matrícula é igual à rh_matricula do professor; se não houver,
--    a de menor número de vínculo.
--  - A planilha tem 5295 IDs funcionais com cargo/disciplina (5483 linhas).
--    Nomes dos professores ficam fora do script de propósito (LGPD).
-- Requisito: a coluna area_atuacao precisa existir (supabase_professor_area_atuacao.sql).
-- =============================================================================

BEGIN;

SET LOCAL lock_timeout = '10s';

CREATE TEMP TABLE _planilha (
    id_funcional varchar(50)  NOT NULL,
    matricula    varchar(50)  NOT NULL,
    vinculo      integer      NOT NULL,
    nome_cargo   varchar(150) NOT NULL,
    disciplina   varchar(150) NOT NULL
) ON COMMIT DROP;

