-- Uma linha por professor existente (matrícula igual primeiro; senão o menor vínculo).
CREATE TEMP TABLE _escolhida ON COMMIT DROP AS
SELECT DISTINCT ON (p.id)
       p.id AS professor_id, pl.nome_cargo, pl.disciplina
FROM public.harpiadb_professores_professor p
JOIN _planilha pl ON pl.id_funcional = p."ID_FUNCIONAL"
ORDER BY p.id,
         (pl.matricula <> '' AND pl.matricula = COALESCE(p.rh_matricula, '')) DESC,
         pl.vinculo ASC;

-- 1) Cargo -> tipo de contrato de mesmo nome.
UPDATE public.harpiadb_professores_professor p
SET tipo_contrato_id = tc.id
FROM _escolhida e
JOIN public.harpiadb_professores_tipo_contrato tc ON tc.nome = e.nome_cargo
WHERE p.id = e.professor_id
  AND e.nome_cargo <> ''
  AND p.tipo_contrato_id IS DISTINCT FROM tc.id;

-- 2) Disciplina -> area de atuacao.
UPDATE public.harpiadb_professores_professor p
SET area_atuacao = e.disciplina
FROM _escolhida e
WHERE p.id = e.professor_id
  AND e.disciplina <> ''
  AND p.area_atuacao IS DISTINCT FROM e.disciplina;

-- Relatorio 1: cargos da planilha SEM tipo de contrato igual no sistema (nao foram aplicados).
SELECT e.nome_cargo AS cargo_sem_tipo_de_contrato, count(*) AS professores
FROM _escolhida e
WHERE e.nome_cargo <> ''
  AND NOT EXISTS (SELECT 1 FROM public.harpiadb_professores_tipo_contrato tc WHERE tc.nome = e.nome_cargo)
GROUP BY e.nome_cargo
ORDER BY professores DESC;

-- Relatorio 2: professores do sistema que nao constam na planilha.
SELECT count(*) AS professores_fora_da_planilha
FROM public.harpiadb_professores_professor p
WHERE NOT EXISTS (SELECT 1 FROM _planilha pl WHERE pl.id_funcional = p."ID_FUNCIONAL");

COMMIT;
